-- Normaliza cosecha contra public.campos por potrero + bloque exacto.
update public.cosecha_analisis ca
set campo_id = c.id,
    potrero_normalizado = c.potrero,
    bloque_normalizado = c.bloque,
    especie = case when ca.especie in ('', 'SIN ESPECIE') then c.especie else ca.especie end,
    variedad = case when ca.variedad in ('', 'SIN VARIEDAD') then upper(c.variedad) else ca.variedad end
from public.campos c
where ca.campo_id is null
  and public.agrocore_normalizar_texto(c.potrero) = public.agrocore_normalizar_texto(ca.potrero_normalizado)
  and public.agrocore_normalizar_texto(c.bloque) = public.agrocore_normalizar_texto(ca.bloque_normalizado);

-- Caso especial paltos: en el Excel historico viene potrero 26 con bloques tipo D1/E2/I5.
-- En public.campos esos sectores viven como potreros D/E/F/G/H/I/J y bloque numerico.
with matches as (
  select
    ca.id,
    c.id as campo_id,
    c.potrero,
    c.bloque
  from public.cosecha_analisis ca
  join public.campos c
    on public.agrocore_normalizar_texto(coalesce(ca.potrero_excel, ca.potrero_normalizado)) = '26'
   and public.agrocore_normalizar_texto(c.potrero) = substring(public.agrocore_normalizar_texto(coalesce(ca.bloque_excel, ca.bloque_normalizado, ca.bloque_formula)) from '^([a-z])\s*0*[0-9]+$')
   and public.agrocore_normalizar_texto(c.bloque) = regexp_replace(public.agrocore_normalizar_texto(coalesce(ca.bloque_excel, ca.bloque_normalizado, ca.bloque_formula)), '^[a-z]\s*0*([0-9]+)$', '\1')
)
update public.cosecha_analisis ca
set campo_id = m.campo_id,
    potrero_normalizado = m.potrero,
    bloque_normalizado = m.bloque
from matches m
where ca.id = m.id;

-- Caso especial: potrero 27 puede venir resumido; solo asigna campo_id cuando el bloque no es ambiguo.
with matches as (
  select ca.id, (array_agg(c.id order by c.id::text))[1] as campo_id, count(*) as coincidencias
  from public.cosecha_analisis ca
  join public.campos c
    on public.agrocore_normalizar_texto(c.potrero) like '27%'
   and public.agrocore_normalizar_texto(c.bloque) = public.agrocore_normalizar_texto(ca.bloque_normalizado)
   and public.agrocore_normalizar_texto(c.variedad) = public.agrocore_normalizar_texto(ca.variedad)
  where ca.campo_id is null
    and public.agrocore_normalizar_texto(ca.potrero_normalizado) = '27'
  group by ca.id
  having count(*) = 1
)
update public.cosecha_analisis ca
set campo_id = m.campo_id
from matches m
where ca.id = m.id;

-- Exportacion no tiene bloque: guarda todos los campos compatibles en campo_ids.
with matches as (
  select
    ea.id,
    array_agg(c.id order by c.potrero, c.bloque) as campo_ids,
    string_agg(distinct c.especie, ' / ' order by c.especie) as especie_match
  from public.exportacion_analisis ea
  join public.campos c
    on public.agrocore_normalizar_texto(c.variedad) = public.agrocore_normalizar_texto(ea.variedad)
   and (
        public.agrocore_normalizar_texto(c.potrero) = public.agrocore_normalizar_texto(ea.potrero_normalizado)
        or (public.agrocore_normalizar_texto(ea.potrero_normalizado) = '27' and public.agrocore_normalizar_texto(c.potrero) like '27%')
        or (public.agrocore_normalizar_texto(ea.potrero_normalizado) = '26' and public.agrocore_normalizar_texto(c.potrero) in ('d','e','f','g','h','i','j'))
      )
  group by ea.id
)
update public.exportacion_analisis ea
set campo_ids = m.campo_ids,
    especie = coalesce(nullif(ea.especie, ''), m.especie_match)
from matches m
where ea.id = m.id;

commit;
